[metadata] {"type": "create", "filePath": "/workspace/repo/src/schemas/json/yamlfmt.json", "content": "{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemastore.org/yamlfmt.json",
  "title": "yamlfmt configuration",
  "description": "Configuration file for yamlfmt, an extensible command line tool to format YAML files.",
  "type": "object",
  "definitions": {
    "lineEnding": {
      "description": "Parse and write the file with \"lf\" or \"crlf\" line endings.",
      "type": "string",
      "enum": ["lf", "crlf"]
    },
    "basicFormatter": {
      "description": "The default formatter, based on the yaml.v3 library.",
      "type": "object",
      "properties": {
        "type": {
          "description": "The type of formatter to use.",
          "type": "string",
          "enum": ["basic"]
        },
        "indent": {
          "description": "The indentation level in spaces to use for the formatted YAML.",
          "type": "integer"
        },
        "include_document_start": {
          "description": "Include the document start marker (---) at the beginning of documents.",
          "type": "boolean"
        },
        "line_ending": {
          "$ref": "#/definitions/lineEnding"
        },
        "retain_line_breaks": {
          "description": "Retain line breaks in formatted YAML.",
          "type": "boolean"
        },
        "retain_line_breaks_single": {
          "description": "The same as retain_line_breaks, but collapses multiple consecutive empty lines into a single empty line.",
          "type": "boolean"
        },
        "disallow_anchors": {
          "description": "If true, throw an error if anchors or aliases are present.",
          "type": "boolean"
        },
        "max_line_length": {
          "description": "Set the maximum line length. If retain_line_breaks is enabled, then the max_line_length may be exceeded to preserve them.",
          "type": "integer"
        },
        "scan_folded_as_literal": {
          "description": "Parse values that are formatted in folded style (i.e. with the '>' character) into a single line, thus removing the folding.",
          "type": "boolean"
        },
        "indentless_arrays": {
          "description": "Render array elements at the same indentation level as the object they are nested in.",
          "type": "boolean"
        },
        "drop_merge_tag": {
          "description": "Assume that any invalid map key that is inline and begins with a '<<' merge is a merge key, and attempt to treat it as such.",
          "type": "boolean"
        },
        "pad_line_comments": {
          "description": "The number of padding spaces to insert before line comments.",
          "type": "integer"
        },
        "trim_trailing_whitespace": {
          "description": "Trim trailing whitespace from lines.",
          "type": "boolean"
        },
        "eof_newline": {
          "description": "Always add a newline at end of file. Useful in the scenario where retain_line_breaks is enabled and there is no newline at the end of the file.",
          "type": "boolean"
        },
        "strip_directives": {
          "description": "Strip any YAML directives (i.e. lines that begin with '%', such as the '%YAML' directive).",
          "type": "boolean"
        },
        "array_indent": {
          "description": "The indentation level in spaces to use for arrays specifically. Defaults to the value of indent.",
          "type": "integer"
        },
        "indent_root_array": {
          "description": "Adds indentation to sequences (arrays) at the root of the document.",
          "type": "boolean"
        },
        "disable_alias_key_correction": {
          "description": "Disable the alias key correction, which restores the values of merge keys that were aliased.",
          "type": "boolean"
        },
        "force_array_style": {
          "description": "Force the style of arrays (sequences) to either flow or block.",
          "type": "string",
          "enum": ["", "flow", "block"]
        },
        "force_quote_style": {
          "description": "Force the style of quoted scalars to either single or double.",
          "type": "string",
          "enum": ["", "single", "double"]
        }
      }
    },
    "kyamlFormatter": {
      "description": "The kyaml formatter, based on the kubernetes-sigs/yaml library. It does not accept any of the basic formatter config options.",
      "type": "object",
      "properties": {
        "type": {
          "description": "The type of formatter to use.",
          "type": "string",
          "const": "kyaml"
        }
      },
      "required": ["type"],
      "additionalProperties": false
    }
  },
  "properties": {
    "line_ending": {
      "$ref": "#/definitions/lineEnding"
    },
    "doublestar": {
      "description": "Use doublestar for include and exclude paths.",
      "type": "boolean"
    },
    "continue_on_error": {
      "description": "Continue formatting and don't exit with code 1 when there is an invalid YAML file found.",
      "type": "boolean"
    },
    "match_type": {
      "description": "The strategy used to match files for formatting.",
      "type": "string",
      "enum": ["standard", "doublestar", "gitignore"]
    },
    "include": {
      "description": "The paths for the command to include for formatting.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "exclude": {
      "description": "The paths for the command to exclude from formatting.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "gitignore_excludes": {
      "description": "Use gitignore files to exclude paths from formatting.",
      "type": "boolean"
    },
    "gitignore_path": {
      "description": "The path to the gitignore file(s) to use.",
      "type": "string"
    },
    "regex_exclude": {
      "description": "Regex patterns to exclude from formatting. Distinct from exclude, since exclude only operates on paths.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "extensions": {
      "description": "The extensions to use for standard match_type.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "formatter": {
      "description": "The formatter configuration.",
      "type": "object",
      "oneOf": [
        {
          "$ref": "#/definitions/basicFormatter"
        },
        {
          "$ref": "#/definitions/kyamlFormatter"
        }
      ]
    },
    "output_format": {
      "description": "The format to use for command output.",
      "type": "string",
      "enum": ["default", "line", "gitlab"]
    }
  }
}
